select e->>0, e->>1, e->>2, e->>3, (e->>4)::int, true, 'internal_research',
       (select id from occumed_core.source_documents where source_key='insight_hub_relevance_vocabulary_20261003'), false,
       case when e->>0='rfp_commodity_and_equipment_supply' then '{"new_not_from_code":true,"origin":"requested regression coverage for commodity/raw-material rejection"}'::jsonb else '{"migration":"relevance_vocabulary_20261003"}'::jsonb end
from jsonb_array_elements($j$[["rfp_primary_purchased_scope","rfp_judge","Judge the primary purchased scope, not incidental boilerplate","Approve an opportunity only when the PRIMARY PURCHASED SCOPE requires occupational health, employee medical examinations, drug/alcohol testing, medical surveillance, audiometry, spirometry, respirator medical evaluation or fit testing, vaccinations, deployment medical screening, fitness-for-duty evaluations, or management of a provider network delivering those services. Reject records where medical, health, workforce, safety, testing or regulatory words appear only in clauses, background text, agency descriptions or generic boilerplate.",90],["rfp_realistic_bid","rfp_judge","Occu-Med must be able to bid","Approve only when Occu-Med could realistically bid as the prime contractor or as a meaningful subcontractor.",85],["rfp_semantic_equivalents","rfp_extract","Understand semantic equivalents","Treat these as equivalent to Occu-Med service language: workforce health, employee medical surveillance, pre-placement examinations, respiratory protection programs, audiometric conservation, deployment medical screening, occupational testing, and provider-network administration.",80],["rfp_unrelated_scope_examples","rfp_judge","Unrelated purchases to reject","Reject construction, corrosion repair, painting, snow removal, parking garages, chillers, toilets, surveillance cameras, IT, laboratory equipment purchases, EEG systems, DNA extraction systems, weapons, facilities maintenance, treatment-only clinical care, general clinical staffing, insurance administration, grants, jobs and news, even when the notice contains incidental health or safety language.",85],["rfp_commodity_and_equipment_supply","rfp_judge","Commodity, raw-material and equipment supply is not Occu-Med scope","Bulk commodity, raw-material, equipment and supplies purchases (for example metals, fuel, chemicals, drug-testing kits or laboratory supplies without a service component) are out of scope. A contractor-compliance clause such as maintaining a drug-testing policy does not make the purchase relevant. Canonical rule: rv_commodity_raw_material_supply.",85]]$j$::jsonb) e;
commit;
